DictionaryWord getWordOfTheDay() {
  final now = DateTime.now();
  final dayOfYear = now.difference(DateTime(now.year, 1, 1)).inDays;
  return dictionaryWords[dayOfYear % dictionaryWords.length];
}


List<DictionaryWord> searchWords(String query) {
  final lowerQuery = query.toLowerCase().trim();
  if (lowerQuery.isEmpty) return [];
  
  return dictionaryWords.where((word) {
    // Search in English word
    if (word.word.toLowerCase().contains(lowerQuery)) return true;
    
    // Search in bagobo word (including comma-separated parts)
    if (_containsInDelimited(word.bagoboWord.toLowerCase(), lowerQuery)) return true;
    
    // Search in tagalog word (including comma-separated parts)
    if (_containsInDelimited(word.tagalog.toLowerCase(), lowerQuery)) return true;
    
    // Search in bisaya word (including comma-separated parts)
    if (_containsInDelimited(word.bisaya.toLowerCase(), lowerQuery)) return true;
    
    // Search in description
    if (word.description.toLowerCase().contains(lowerQuery)) return true;
    
    return false;
  }).toList();
}

bool _containsInDelimited(String text, String query) {
  if (text.contains(query)) return true;
  // Also check individual parts if text contains commas
  if (text.contains(',')) {
    var parts = text.split(',').map((p) => p.trim());
    for (var part in parts) {
      if (part.contains(query)) return true;
    }
  }
  return false;
}

List<DictionaryWord> getWordsByCategory(String categoryId) {
  final category = categories.firstWhere(
    (c) => c.id == categoryId,
    orElse: () => categories.first,
  );
  return dictionaryWords.where((word) => word.category == category.name).toList();
}